on conflict (id) do nothing;

-- Placeholder walk times until the Phase 0 walk-around measures them.
select s.id, d.id, 10
from public.shops s cross join public.drop_points d
where s.id in ('1b49b574-f12e-4a50-8fcf-cd452cd8f9c8', '54477a30-8971-4648-841b-6d397da37cc9')
on conflict (shop_id, drop_point_id) do nothing;

-- Replace the four sample shops from seed.sql on shared databases: move anyone approved for or working
-- at one to 4H Canteen, then remove the sample shops that have no orders. (Local `supabase db reset`
-- and db-tests load seed.sql after migrations, so the samples still exist there.)
update public.allowed_logins set shop_id = '54477a30-8971-4648-841b-6d397da37cc9' where shop_id in ('00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000002', '00000000-0000-4000-8000-000000000003', '00000000-0000-4000-8000-000000000004');

select '54477a30-8971-4648-841b-6d397da37cc9', profile_id, role from public.shop_staff where shop_id in ('00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000002', '00000000-0000-4000-8000-000000000003', '00000000-0000-4000-8000-000000000004')
on conflict (shop_id, profile_id) do nothing;

delete from public.shops s
where s.id in ('00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000002', '00000000-0000-4000-8000-000000000003', '00000000-0000-4000-8000-000000000004')
  and not exists (select 1 from public.orders o where o.shop_id = s.id);
